import {WebSocket} from 'ws';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import type {SessionListOptions} from '../../types/sessionStore.js';
import {validateMessage} from './validation.js';
import {startEngineWith, connectClient, stopEngines} from '../wsTestSupport.js';
import {setLogger} from '../../shared/logger.js';

interface Frame {
  type: string;
  code?: string;
  conversations?: Array<Record<string, unknown>>;
}

class RecordedSessionStore extends InMemorySessionStore {
  listedUserId: string | number | undefined;
  listedOptions: SessionListOptions | undefined;

  override listFor(userId: string | number, options?: SessionListOptions) {
    this.listedUserId = userId;
    this.listedOptions = options;
    return super.listFor(userId, options);
  }
}

afterEach(async () => {
  await stopEngines();
});

beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

const request = (url: string, message: Record<string, unknown>): Promise<Frame> => {
  const client = connectClient(url);
  return new Promise<Frame>((resolve, reject) => {
    client.on('error', reject);
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame & {sessionId?: string};
      if (frame.type === 'connected') {
        client.send(JSON.stringify(message));
      } else if (frame.type === 'conversation_list' || frame.type === 'error') {
        resolve(frame);
      }
    });
  });
};

describe('conversation list WebSocket protocol', () => {
  // spec: specs/hal-engine-websocket-protocol/spec.md#1
  it('validates list_conversations limits and its composite before cursor', () => {
    expect(validateMessage({type: 'list_conversations'})).toEqual({
      valid: true,
      data: {type: 'list_conversations'},
    });

    for (const [field, value] of [
      ['limit', 0],
      ['limit', 201],
      ['limit', 1.5],
      ['limit', '10'],
      ['before', 'not a cursor'],
    ] as const) {
      const result = validateMessage({type: 'list_conversations', [field]: value});
      expect(result.valid).toBe(false);
      if (!result.valid) expect(result.error).toContain(field);
    }
  });

  // spec: specs/hal-engine-conversation-list/spec.md#1
  it('lists only the authenticated user’s summaries as ISO wire values', async () => {
    const store = new RecordedSessionStore();
    store.create('u1-old', 'u1').entries.push({role: 'user', content: 'old', timestamp: '2026-01-01T00:00:00.000Z'});
    store.create('u1-new', 'u1').entries.push({role: 'user', content: 'new', timestamp: '2026-01-02T00:00:00.000Z'});
    store.create('u2-only', 'u2');

    const {url} = await startEngineWith({
      sessionStore: store,
      history: {enabled: true},
    } as Parameters<typeof startEngineWith>[0]);
    const frame = await request(url, {type: 'list_conversations', userId: 'u2'});

    expect(store.listedUserId).toBe('u1');
    expect(frame.type).toBe('conversation_list');
    expect(frame.conversations).toHaveLength(3);
    expect(frame.conversations?.map(row => row.sessionId)).toEqual(expect.arrayContaining(['u1-old', 'u1-new']));
    for (const summary of frame.conversations ?? []) {
      expect(Object.keys(summary).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
      expect(summary.createdAt).toEqual(expect.stringMatching(/^\d{4}-\d{2}-\d{2}T/));
      expect(summary.updatedAt).toEqual(expect.stringMatching(/^\d{4}-\d{2}-\d{2}T/));
    }
  });

  // spec: specs/hal-engine-conversation-list/spec.md#14
  it('passes limit and the JSON-safe before cursor to listFor', async () => {
    const store = new RecordedSessionStore();
    store.create('u1-old', 'u1');
    const {url} = await startEngineWith({
      sessionStore: store,
      history: {enabled: true},
    } as Parameters<typeof startEngineWith>[0]);

