function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit)) {
      return {valid: false, error: 'list_conversations limit must be an integer'};
    }
    if (message.limit < 1 || message.limit > 200) {
      return {valid: false, error: 'list_conversations limit must be between 1 and 200'};
    }
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null || Array.isArray(message.before)) {
      return {valid: false, error: 'list_conversations before must be a cursor object'};
    }
    const cursor = message.before as Record<string, unknown>;
    if (typeof cursor.updatedAt !== 'string' || isNaN(Date.parse(cursor.updatedAt))) {
      return {valid: false, error: 'list_conversations before.updatedAt must be a valid date string'};
    }
    if (typeof cursor.sessionId !== 'string') {
      return {valid: false, error: 'list_conversations before.sessionId must be a string'};
    }
  }

  const data: {type: 'list_conversations'; limit?: number; before?: ConversationCursor} = {
    type: 'list_conversations',
  };
  if (typeof message.limit === 'number') data.limit = message.limit;
  if (message.before !== undefined) {
    const cursor = message.before as Record<string, unknown>;
    data.before = {updatedAt: cursor.updatedAt as string, sessionId: cursor.sessionId as string};
  }

  return {valid: true, data};
}

