// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

function isListConversationsFrame(rawMessage: unknown): boolean {
  return (
    typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'list_conversations'
  );
}

async function answerListConversations(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined,
  history: HistoryOptions | undefined
): Promise<void> {
  if (!validation.valid) {
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  if (!history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
    return;
  }

  if (typeof sessionStore?.listFor !== 'function') {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'This store does not support listing conversations');
    return;
  }

  const msg = validation.data;
  if (msg.type !== 'list_conversations') return;

  let summaries: SessionSummary[];
  try {
    summaries = await sessionStore.listFor(session.userId, {limit: msg.limit, before: msg.before});
  } catch (error) {
    log.error('message', 'listFor failed', {sessionId: session.sessionId, error: error instanceof Error ? error.message : 'unknown'});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
    return;
  }

  const conversations: ConversationSummary[] = summaries.map(s => ({
    sessionId: s.sessionId,
    createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
    updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
    entryCount: s.entryCount,
  }));

  sendJson(ws, {type: 'conversation_list', conversations});
}

